create type public.app_role as enum ('admin', 'user');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role public.app_role not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,role));
grant select on public.user_roles to authenticated;
grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create policy own_roles on public.user_roles for select to authenticated using (user_id = (select auth.uid()));
create function public.has_role(_user_id uuid, _role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
revoke all on function public.has_role(uuid,public.app_role) from public;
grant execute on function public.has_role(uuid,public.app_role) to authenticated;
insert into public.user_roles(user_id,role) values ('be6e5830-3180-4e86-b7b8-2c0f4bf77dc4','admin');
create table public.events (id uuid primary key default gen_random_uuid(), title text not null, schedule_text text not null default '', icon text not null default 'calendar', destination_url text, starts_at timestamptz, ends_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
grant select on public.events to anon;
grant select,insert,update,delete on public.events to authenticated;
grant all on public.events to service_role;
alter table public.events enable row level security;
create policy active_events on public.events for select to anon,authenticated using (starts_at <= now() and ends_at > now() and destination_url is not null);
create policy admin_events on public.events for all to authenticated using (public.has_role((select auth.uid()),'admin')) with check (public.has_role((select auth.uid()),'admin'));
create function public.validate_event() returns trigger language plpgsql set search_path=public as $$ begin
 if length(trim(new.title)) < 1 or length(new.title)>120 then raise exception 'Event title must be 1 to 120 characters'; end if;
 if length(new.schedule_text)>180 then raise exception 'Schedule text is too long'; end if;
 if new.icon not in ('mountain','palm','store','calendar','radio','users','church','book','heart','mic') then raise exception 'Invalid event icon'; end if;
 if new.destination_url is not null and new.destination_url !~* '^https?://[^[:space:]]+$' then raise exception 'Destination must be an HTTP or HTTPS link'; end if;
 if (new.starts_at is null) <> (new.ends_at is null) then raise exception 'Both schedule dates are required'; end if;
 if new.starts_at is not null and new.ends_at <= new.starts_at then raise exception 'End must be after start'; end if;
 if new.starts_at is not null and new.destination_url is null then raise exception 'Scheduled events need a destination link'; end if;
 new.updated_at=now(); return new; end $$;
create trigger validate_event before insert or update on public.events for each row execute function public.validate_event();
create index events_schedule_idx on public.events(starts_at,ends_at);
insert into public.events(title,schedule_text,icon) values ('Counseling','12 September 2026','mountain'), ('Teaching on radio','Monday to Friday','palm'), ('Leaders Conference','13 July 2026','store');